// ─── internal.mediaAssets.byOriginalFileName ──────────────────────────────────

/**
 * Returns a single non-archived mediaAsset doc by originalFileName, or null.
 * Uses by_originalFileName index (RA-17).
 *
 * internalQuery — called by the Node seed CLI via `bunx convex run
 * internal.mediaAssets.byOriginalFileName`. No public browser surface.
 *
 * Returns the first doc with status=reserved|active for this filename.
 * Archived assets are NOT returned so a re-seed after archiving creates a
 * fresh asset instead of being permanently blocked (MEDIUM-2).
 */
export const byOriginalFileName = internalQuery({
  args: { originalFileName: v.string() },
  handler: async (ctx, args) => {
    const result = await ctx.db
      .query('mediaAssets')
      .withIndex('by_originalFileName', (q) => q.eq('originalFileName', args.originalFileName))
      .first();
    if (!result || result.status === 'archived') return null;
    return result;
  },
});
[/external_agent_tool_result]

