// --- archive --------------------------------------------------------------
const pad = (n) => String(n).padStart(3, '0');

function compressRange(nums, prefix) {
  nums.sort((a, b) => a - b);
  const parts = [];
  for (let i = 0; i < nums.length; ) {
    let j = i;
    while (j + 1 < nums.length && nums[j + 1] === nums[j] + 1) j += 1;
    parts.push(i === j
      ? `<code>${prefix}-${pad(nums[i])}</code>`
      : `<code>${prefix}-${pad(nums[i])}</code> à <code>${prefix}-${pad(nums[j])}</code>`);
    i = j + 1;
  }
  return parts.join(', ');
}

function archive(wave) {
  if (!wave) die('--archive requires a wave name');
  const w = wave.trim().toLowerCase();
  let active = readFileSync(ACTIVE, 'utf8');

  const re = new RegExp(
    `<article\\b[^>]*\\sid="(deferred-${w}-\\d+)"[^>]*\\sdata-impl="resolved"[^>]*>`, 'g');
  const ids = [...active.matchAll(re)].map((m) => m[1]);
  if (ids.length === 0) die(`no resolved "${w}" entries in active backlog`);

  const archiveName = readdirSync(ARCHIVE_DIR)
    .find((f) => f.endsWith('-resolved.html') && f.includes(`-${w}-`));
  if (!archiveName) {
    die(`no archive file for wave "${w}" — seed `
      + `docs/backlog-deferred/_archive/<date>-${w}-cleanup-resolved.html `
      + '(clone an existing archive, empty its registry) then re-run');
  }
  const archivePath = `${ARCHIVE_DIR}/${archiveName}`;

  // cut the articles out of the active file, right-to-left to keep offsets valid
  const spans = ids.map((id) => findArticle(active, id)).sort((a, b) => b.start - a.start);
  const moved = [];
  for (const s of spans) {
    moved.unshift(active.slice(s.start, s.end));
    let cut = s.start;
    while (cut > 0 && (active[cut - 1] === ' ' || active[cut - 1] === '\t')) cut -= 1;
    if (active[cut - 1] === '\n') cut -= 1;
    active = active.slice(0, cut) + active.slice(s.end);
  }

  // append into the archive, after its last entry
  let arc = readFileSync(archivePath, 'utf8');
  const lastClose = arc.lastIndexOf('</article>');
  if (lastClose === -1) die(`archive ${archiveName} has no entry to append after`);
  const insertAt = lastClose + 10;
  arc = arc.slice(0, insertAt) + moved.map((a) => `\n\n          ${a}`).join('') + arc.slice(insertAt);

  // refresh archive count + id range
  const nums = [...arc.matchAll(/id="deferred-[a-z0-9]+-(\d+)"/g)].map((m) => Number(m[1]));
  const prefix = w.toUpperCase();
  const range = compressRange(nums, prefix);
  const total = nums.length;
  arc = arc.replace(
    /<span class="meta-pill"><strong>\d+ entrées? résolues?<\/strong>.*?<\/span>/s,
    `<span class="meta-pill"><strong>${total} entrées résolues</strong> · IDs ${range}</span>`);
  writeFileSync(archivePath, arc);

  // refresh active counts + §3 index
  const activeCount = (active.match(/<article class="registry-entry"/g) || []).length;
[/external_agent_tool_result]

